CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT, pw_hash TEXT NOT NULL, salt TEXT NOT NULL, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_fail(email TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0, until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, code TEXT, color TEXT, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, course_id INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'exam' CHECK(kind IN ('exam','quiz','assignment')), title TEXT NOT NULL, date TEXT, time TEXT);
CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, course_id INTEGER NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','learning','done')), mins INTEGER NOT NULL DEFAULT 45, sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assess_topics(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, assessment_id INTEGER NOT NULL, topic_id INTEGER NOT NULL, UNIQUE(assessment_id, topic_id));
CREATE TABLE IF NOT EXISTS cards(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, topic_id INTEGER NOT NULL, front TEXT NOT NULL, back TEXT NOT NULL DEFAULT '', due TEXT NOT NULL, ivl INTEGER NOT NULL DEFAULT 0, ease REAL NOT NULL DEFAULT 2.5, reps INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL, notes TEXT, course_id INTEGER, topic_id INTEGER, due TEXT, est INTEGER, priority INTEGER NOT NULL DEFAULT 2 CHECK(priority IN (1,2,3)), done_at TEXT, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS blocks(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, day TEXT NOT NULL, start TEXT NOT NULL, mins INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'task' CHECK(kind IN ('task','fixed','break')), task_id INTEGER, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, task_id INTEGER, start_at TEXT NOT NULL, plan_mins INTEGER, act_mins INTEGER, pauses INTEGER NOT NULL DEFAULT 0, end_kind TEXT NOT NULL DEFAULT 'open' CHECK(end_kind IN ('open','done','stopped','abandoned')), rating INTEGER);
CREATE TABLE IF NOT EXISTS timer(user_id INTEGER PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS habits(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, per_week INTEGER NOT NULL DEFAULT 7, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS hlog(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, habit_id INTEGER NOT NULL, day TEXT NOT NULL, UNIQUE(habit_id, day));
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, course_id INTEGER, title TEXT, body TEXT NOT NULL DEFAULT '', pinned INTEGER NOT NULL DEFAULT 0, updated TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS prefs(user_id INTEGER NOT NULL, k TEXT NOT NULL, v TEXT, PRIMARY KEY(user_id, k));
CREATE INDEX IF NOT EXISTS idx_courses_user ON courses(user_id);
CREATE INDEX IF NOT EXISTS idx_assessments_user ON assessments(user_id);
CREATE INDEX IF NOT EXISTS idx_topics_user ON topics(user_id);
CREATE INDEX IF NOT EXISTS idx_assess_topics_user ON assess_topics(user_id);
CREATE INDEX IF NOT EXISTS idx_cards_user ON cards(user_id);
CREATE INDEX IF NOT EXISTS idx_tasks_user ON tasks(user_id);
CREATE INDEX IF NOT EXISTS idx_blocks_user ON blocks(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_habits_user ON habits(user_id);
CREATE INDEX IF NOT EXISTS idx_hlog_user ON hlog(user_id);
CREATE INDEX IF NOT EXISTS idx_notes_user ON notes(user_id);
CREATE INDEX IF NOT EXISTS idx_blocks_day ON blocks(user_id, day);
CREATE INDEX IF NOT EXISTS idx_sessions_start ON sessions(user_id, start_at);
CREATE INDEX IF NOT EXISTS idx_cards_due ON cards(user_id, due);
CREATE INDEX IF NOT EXISTS idx_auth_user ON auth_sessions(user_id);
